Method.Implementation:
Set tStatus = $$$OK
Try {
	If '$IsObject($get(pBatch)) Set tStatus = $$$ERROR($$$ObjectInstanceRequired) Quit
	If '$IsObject(pIOStream) {
		Set tFilename = pIOStream
		Set pIOStream = ##class(%IO.FileStream).%New()
		Do pIOStream.Open(tFilename,"WAE",,"UTF-8",.tStatus)
		If $$$ISERR(tStatus) Quit
	}
	If $IsObject(pBatch.Request) {
		Set tStatus = ##class(IHC.ITF.EDIPAYER.DStruc.Email278update).PutObject(pIOStream,pBatch.Request,0)
		If $$$ISERR(tStatus) Quit
	}
	Set seqKey = ""
	For {
		Set tElement = pBatch.ServiceLevel.GetNext(.seqKey)
		If (seqKey = "") Quit
		If $IsObject(tElement) {
			Set tStatus = tElement.PutSequence(pIOStream)
			If $$$ISERR(tStatus) Quit
		}
		Set tStatus = pBatch.ServiceLevel.%UnSwizzleAt(seqKey)
		If $$$ISERR(tStatus) Quit
	}
	If $$$ISERR(tStatus) Quit
	If $IsObject(pBatch.Message) {
		Set tStatus = ##class(IHC.ITF.ITFCOMMON.DStruc.Message).PutObject(pIOStream,pBatch.Message,0)
		If $$$ISERR(tStatus) Quit
	}
	Do pIOStream.Flush(.tStatus)
	If $$$ISERR(tStatus) Quit
} Catch ex {
	Set tStatus = $$$SystemError
}
Quit tStatus

Set tStatus = $$$OK
Try {
	If '$IsObject(pIOStream) {
		Set tFilename = pIOStream
		Set pIOStream = ##class(%IO.FileStream).%New()
		Do pIOStream.Open(tFilename,,pTimeout,"UTF-8",.tStatus)
		If $$$ISERR(tStatus) Quit
	}
	Set pIOStream.CharEncoding = "UTF-8"
	Set pBatch = ##class(IHC.ITF.DStruc.Record.Sh278ToEmail.Batch).%New()
	Set pBatch.%Source = pIOStream.Name
	Set pLookAhead = $get(pLookAhead)
	If (14 > $length(pLookAhead)) {
		Set pLookAhead = pLookAhead _ pIOStream.Read(14-$length(pLookAhead),pTimeout,.tStatus)
		If $$$ISERR(tStatus) Quit
	}
	If ($extract(pLookAhead,1,14) = "email278update") {
		Set tStatus = ##class(IHC.ITF.EDIPAYER.DStruc.Email278update).GetObject(pIOStream,.tObject,pTimeout,.pLookAhead)
		If $$$ISERR(tStatus) Set tStatus = $system.Status.AppendStatus($$$ERROR($$$EnsRecordMapErrComplexBasic,"Request","IHC.ITF.EDIPAYER.DStruc.Email278update",$classname()),tStatus) Quit
		Set pBatch.Request = tObject
	}
	If (5 > $length(pLookAhead)) {
		Set pLookAhead = pLookAhead _ pIOStream.Read(5-$length(pLookAhead),pTimeout,.tStatus)
		If $$$ISERR(tStatus) Set tStatus = $system.Status.AppendStatus($$$ERROR($$$EnsRecordMapErrComplexBasic,"ServiceLevel","IHC.ITF.DStruc.Record.Sh278ToEmail.ServiceLevel",$classname()),tStatus) Quit
	}
	Set tCount = 0
	While ($extract(pLookAhead,1,5)="2000F") {
		Set tStatus = ..getSeqServiceLevel(pIOStream,.tSequence,.pLookAhead,pBatch,pTimeout)
		Set tCount = tCount + 1
		If $$$ISERR(tStatus) Quit
		Set tStatus = tSequence.%Save()
		If $$$ISERR(tStatus) Quit
		Set tStatus = pBatch.ServiceLevel.SetAt(tSequence,tCount)
		If $$$ISERR(tStatus) Quit
		Set tStatus = pBatch.ServiceLevel.%UnSwizzleAt(tCount)
		If $$$ISERR(tStatus) Quit
		If (5 > $length(pLookAhead)) {
			Set pLookAhead = pLookAhead _ pIOStream.Read(5-$length(pLookAhead),pTimeout,.tStatus)
			If $$$ISERR(tStatus) Quit
		}
	}
	If $$$ISERR(tStatus) Set tStatus = $system.Status.AppendStatus($$$ERROR($$$EnsRecordMapErrComplexRepeating,"ServiceLevel","IHC.ITF.DStruc.Record.Sh278ToEmail.ServiceLevel",$classname(),tCount),tStatus) Quit
	If (7 > $length(pLookAhead)) {
		Set pLookAhead = pLookAhead _ pIOStream.Read(7-$length(pLookAhead),pTimeout,.tStatus)
		If $$$ISERR(tStatus) Quit
	}
	If ($extract(pLookAhead,1,7) = "message") {
		Set tStatus = ##class(IHC.ITF.ITFCOMMON.DStruc.Message).GetObject(pIOStream,.tObject,pTimeout,.pLookAhead)
		If $$$ISERR(tStatus) Set tStatus = $system.Status.AppendStatus($$$ERROR($$$EnsRecordMapErrComplexBasic,"Message","IHC.ITF.ITFCOMMON.DStruc.Message",$classname()),tStatus) Quit
		Set pBatch.Message = tObject
	}
} Catch {
	Set tStatus = $$$SystemError
}
Quit tStatus

Set tStatus = $$$OK
Try {
	Set pSequence = ##class(IHC.ITF.DStruc.Record.Sh278ToEmail.Record1).%New()
	If (5 > $length(pLookAhead)) {
		Set pLookAhead = pLookAhead _ pIOStream.Read(5-$length(pLookAhead),pTimeout,.tStatus)
		If $$$ISERR(tStatus) Quit
	}
	Set tCount = 0
	While ($extract(pLookAhead,1,5) = "2000F") {
		Set tStatus = ##class(IHC.ITF.ITFCOMMON.DStruc.Sh2782000F).GetObject(pIOStream,.tObject,pTimeout,.pLookAhead)
		Set tCount = tCount + 1
		If $$$ISERR(tStatus) Quit
		Set tStatus = tObject.%Save()
		If $$$ISERR(tStatus) Quit
		Set tStatus = pSequence.Record2.SetAt(tObject,tCount)
		If $$$ISERR(tStatus) Quit
		Set tStatus = pSequence.Record2.%UnSwizzleAt(tCount)
		If $$$ISERR(tStatus) Quit
		If (5 > $length(pLookAhead)) {
			Set pLookAhead = pLookAhead _ pIOStream.Read(5-$length(pLookAhead),pTimeout,.tStatus)
			If $$$ISERR(tStatus) Quit
		}
	}
	If $$$ISERR(tStatus) Set tStatus = $system.Status.AppendStatus($$$ERROR($$$EnsRecordMapErrComplexRepeating,"Record2","IHC.ITF.ITFCOMMON.DStruc.Sh2782000F",$classname(),tCount),tStatus) Quit
}
Catch {
	Set tStatus = $$$SystemError
}
Quit tStatus

Set tStatus = $$$OK
Try {
	Set pSequence = ##class(IHC.ITF.DStruc.Record.Sh278ToEmail.ServiceLevel).%New()
	If (5 > $length(pLookAhead)) {
		Set pLookAhead = pLookAhead _ pIOStream.Read(5-$length(pLookAhead),pTimeout,.tStatus)
		If $$$ISERR(tStatus) Quit
	}
	If ($extract(pLookAhead,1,5) = "2000F") {
		Set tStatus = ##class(IHC.ITF.ITFCOMMON.DStruc.Sh2782000F).GetObject(pIOStream,.tObject,pTimeout,.pLookAhead)
		If $$$ISERR(tStatus) Set tStatus = $system.Status.AppendStatus($$$ERROR($$$EnsRecordMapErrComplexBasic,"Record","IHC.ITF.ITFCOMMON.DStruc.Sh2782000F",$classname()),tStatus) Quit
		Set pSequence.Record = tObject
	}
}
Catch {
	Set tStatus = $$$SystemError
}
Quit tStatus
